    expect(cart.itemCount).toBe(2);
    const snap = cart.snapshot();
    expect(snap).toHaveLength(1);
    expect(snap[0]!.product.id).toBe("a");
    expect(snap[0]!.quantity).toBe(2);
  });

  it("merges quantity when adding the same product twice", () => {
    cart.add(productA, 2);
    cart.add(productA, 3);
    expect(cart.itemCount).toBe(5);
    expect(cart.snapshot()).toHaveLength(1);
    expect(cart.snapshot()[0]!.quantity).toBe(5);
  });

  it("rejects non-positive quantity on add", () => {
    expect(() => cart.add(productA, 0)).toThrow(RangeError);
    expect(() => cart.add(productA, -1)).toThrow(RangeError);
  });

  it("rejects non-integer quantity on add", () => {
    expect(() => cart.add(productA, 1.5)).toThrow(RangeError);
  });

  it("rejects negative unitPriceCents", () => {
    const bad: Product = { id: "bad", name: "Bad", unitPriceCents: -1 };
    expect(() => cart.add(bad, 1)).toThrow(RangeError);
  });

  it("removes a product and returns true", () => {
    cart.add(productA, 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("returns false when removing unknown product", () => {
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updates quantity of existing product", () => {
    cart.add(productA, 3);
    cart.updateQuantity("a", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("updateQuantity with 0 removes the line", () => {
    cart.add(productA, 3);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toHaveLength(0);
  });

  it("updateQuantity rejects negative quantity", () => {
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("updateQuantity rejects non-integer quantity", () => {
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
  });

  it("updateQuantity throws for unknown product", () => {
    expect(() => cart.updateQuantity("nonexistent", 5)).toThrow(/not in the cart/);
  });

  it("clear empties the cart", () => {
    cart.add(productA, 2);
    cart.add(productB, 1);
    cart.clear();
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toEqual([]);
  });

  it("snapshot returns a deep copy (mutations don't reach cart)", () => {
    cart.add(productA, 1);
    const snap = cart.snapshot();
    snap[0]!.quantity = 999;
    snap[0]!.product.unitPriceCents = 1;
    expect(cart.snapshot()[0]!.quantity).toBe(1);
    expect(cart.snapshot()[0]!.product.unitPriceCents).toBe(1000);
  });
});

describe("Cart — totals / pricing pipeline", () => {
  it("computes subtotal as sum of unitPriceCents * quantity", () => {
    const cart = new Cart();
    cart.add(productA, 2); // 2000
    cart.add(productB, 3); // 6000
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(8000);
  });

  it("empty cart has all-zero totals", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("applies discount policy to subtotal", () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(10),
    });
    cart.add(productA, 10); // subtotal 10000, discount 1000
    const totals = cart.totals();
    expect(totals.discountCents).toBe(1000);
    expect(totals.totalCents).toBe(9000);
  });

  it("clamps discount to [0, subtotal]", () => {
    const overDiscount: DiscountPolicy = {
      computeDiscountCents: () => 999_999,
    };
    const cart = new Cart({ discountPolicy: overDiscount });
    cart.add(productA, 1); // subtotal 1000
    expect(cart.totals().discountCents).toBe(1000);

    const negDiscount: DiscountPolicy = {
      computeDiscountCents: () => -500,
    };
    const cart2 = new Cart({ discountPolicy: negDiscount });
    cart2.add(productA, 1);
    expect(cart2.totals().discountCents).toBe(0);
  });

  it("computes tax on discounted subtotal", () => {
    const cart = new Cart({
      discountPolicy: new FixedAmountDiscountPolicy(2000),
      taxCalculator: new RegionalTaxCalculator({ "US": 0.1 }),
    });
    cart.add(productA, 10); // subtotal 10000, discount 2000, taxable 8000
    const totals = cart.totals();
    expect(totals.taxCents).toBe(800); // 10% of 8000
  });

  it("computes shipping against discounted subtotal and lines", () => {
    const cart = new Cart({
      discountPolicy: new FixedAmountDiscountPolicy(1000),
      shippingCalculator: new FlatShippingCalculator(500, 5000),
    });
    cart.add(productA, 5); // subtotal 5000, discount 1000, discounted 4000 (below threshold)
    expect(cart.totals().shippingCents).toBe(500);
  });

  it("free shipping when discounted subtotal meets threshold", () => {
    const cart = new Cart({
      shippingCalculator: new FlatShippingCalculator(500, 5000),
    });
    cart.add(productA, 5); // subtotal 5000, no discount, discounted 5000 >= 5000
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("totalCents = discountedSubtotal + tax + shipping", () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(10),
      taxCalculator: new RegionalTaxCalculator({ "US": 0.08 }),
      shippingCalculator: new FlatShippingCalculator(599),
      region: "US",
    });
    cart.add(productA, 10); // subtotal 10000
    const totals = cart.totals();
    const discountedSubtotal = 10000 - 1000; // 9000
    const tax = Math.floor(9000 * 0.08); // 720
    expect(totals.subtotalCents).toBe(10000);
    expect(totals.discountCents).toBe(1000);
    expect(totals.taxCents).toBe(tax);
    expect(totals.shippingCents).toBe(599);
    expect(totals.totalCents).toBe(discountedSubtotal + tax + 599);
  });

  it("uses injected region for tax", () => {
    const taxCalc: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(100),
    };
    const cart = new Cart({ taxCalculator: taxCalc, region: "FR" });
    cart.add(productA, 1);
    cart.totals();
    expect(taxCalc.computeTaxCents).toHaveBeenCalledWith(1000, "FR");
  });

  it("defaults to region US", () => {
    const taxCalc: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: taxCalc });
    cart.add(productA, 1);
    cart.totals();
    expect(taxCalc.computeTaxCents).toHaveBeenCalledWith(1000, "US");
  });

  it("clamps negative tax to 0", () => {
    const negativeTax: TaxCalculator = {
      computeTaxCents: () => -100,
    };
    const cart = new Cart({ taxCalculator: negativeTax });
    cart.add(productA, 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const negativeShipping: ShippingCalculator = {
      computeShippingCents: () => -100,
    };
    const cart = new Cart({ shippingCalculator: negativeShipping });
    cart.add(productA, 1);
    expect(cart.totals().shippingCents).toBe(0);
  });
});

describe("Cart — checkout()", () => {
  let cart: Cart;

  beforeEach(() => {
    cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(10),
      region: "US",
    });
    cart.add(productA, 2); // 2000
    cart.add(productB, 1); // 2000
  });

  it("returns totals and lines without any collaborators", async () => {
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(4000);
    expect(result.lines).toHaveLength(2);
  });

  it("refreshes prices via priceFetcher", async () => {
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn()
        .mockResolvedValueOnce(1500) // a → 1500
        .mockResolvedValueOnce(2500), // b → 2500
    };
    const result = await cart.checkout({ priceFetcher });
    // new subtotal: 1500*2 + 2500*1 = 5500
    expect(result.totals.subtotalCents).toBe(5500);
    expect(priceFetcher.fetchPriceCents).toHaveBeenCalledTimes(2);
  });

  it("throws InventoryError when item is unavailable", async () => {
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: false, reason: "sold out" }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const ie = err as InventoryError;
      expect(ie.productId).toBe("a");
      expect(ie.requested).toBe(2);
      expect(ie.message).toBe("sold out");
    }
  });

  it("throws InventoryError on partial-stock denial", async () => {
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 1,
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const ie = err as InventoryError;
      expect(ie.requested).toBe(2);
      expect(ie.available).toBe(1);
    }
  });

  it("passes checkout when inventory is sufficient", async () => {
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(4000);
    expect(inventoryChecker.check).toHaveBeenCalledTimes(2);
  });

  it("passes checkout when availableQuantity equals requested", async () => {
    const inventoryChecker: InventoryChecker = {
      check: vi.fn()
        .mockResolvedValueOnce({ available: true, availableQuantity: 2 }) // a: need 2, have 2
        .mockResolvedValueOnce({ available: true, availableQuantity: 1 }), // b: need 1, have 1
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals).toBeDefined();
  });

  it("uses asyncTaxProvider for tax computation", async () => {
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.08),
    };
    const result = await cart.checkout({ asyncTaxProvider });
    // subtotal 4000, 10% discount = 400, taxable = 3600
    // 8% of 3600 = 288
    expect(result.totals.taxCents).toBe(288);
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US");
  });

  it("propagates asyncTaxProvider failure", async () => {
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
      "tax service down",
    );
  });

  it("combines priceFetcher, inventoryChecker, and asyncTaxProvider", async () => {
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn()
        .mockResolvedValueOnce(500) // a
        .mockResolvedValueOnce(1000), // b
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const result = await cart.checkout({
      priceFetcher,
      inventoryChecker,
      asyncTaxProvider,
    });
    // new subtotal: 500*2 + 1000*1 = 2000
    // discount: 10% of 2000 = 200
    // taxable: 1800, tax: 10% of 1800 = 180
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.totals.discountCents).toBe(200);
    expect(result.totals.taxCents).toBe(180);
  });

  it("checkout on empty cart works", async () => {
    const empty = new Cart();
    const result = await empty.checkout();
    expect(result.totals.totalCents).toBe(0);
    expect(result.lines).toHaveLength(0);
  });

  it("generates default InventoryError message when no reason given", async () => {
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        availableQuantity: 0,
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const ie = err as InventoryError;
      expect(ie.message).toContain("insufficient stock");
      expect(ie.available).toBe(0);
    }
  });

  it("priceFetcher rejection propagates", async () => {
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price API down")),
    };
    await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
      "price API down",
    );
  });

  it("checkout with shipping calculator in cart config", async () => {
    const cartWithShipping = new Cart({
      shippingCalculator: new FlatShippingCalculator(799),
    });
    cartWithShipping.add(productA, 1);
    const result = await cartWithShipping.checkout();
    expect(result.totals.shippingCents).toBe(799);
    expect(result.totals.totalCents).toBe(1000 + 799);
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it("returns 0 for a positive subtotal", () => {
    expect(policy.computeDiscountCents(10_000)).toBe(0);
  });

  it("returns 0 for zero subtotal", () => {
    expect(policy.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for a negative subtotal", () => {
    expect(policy.computeDiscountCents(-500)).toBe(0);
  });
});

describe("PercentageDiscountPolicy", () => {
  it("rejects percent < 0", () => {
    expect(() => new PercentageDiscountPolicy(-1)).toThrow(RangeError);
  });

  it("rejects percent > 100", () => {
    expect(() => new PercentageDiscountPolicy(101)).toThrow(RangeError);
  });

  it("rejects NaN", () => {
    expect(() => new PercentageDiscountPolicy(NaN)).toThrow(RangeError);
  });

  it("rejects Infinity", () => {
    expect(() => new PercentageDiscountPolicy(Infinity)).toThrow(RangeError);
  });

  it("accepts 0%", () => {
    const p = new PercentageDiscountPolicy(0);
    expect(p.computeDiscountCents(10_000)).toBe(0);
  });

  it("accepts 100%", () => {
    const p = new PercentageDiscountPolicy(100);
    expect(p.computeDiscountCents(10_000)).toBe(10_000);
  });

  it("computes 10% of 10000 = 1000", () => {
    const p = new PercentageDiscountPolicy(10);
    expect(p.computeDiscountCents(10_000)).toBe(1_000);
  });

  it("rounds down (floor) fractional cents", () => {
    const p = new PercentageDiscountPolicy(33);
    // 33% of 100 = 33.0 → 33
    expect(p.computeDiscountCents(100)).toBe(33);
    // 33% of 101 = 33.33 → 33
    expect(p.computeDiscountCents(101)).toBe(33);
  });

  it("returns 0 for zero subtotal", () => {
    const p = new PercentageDiscountPolicy(50);
    expect(p.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    const p = new PercentageDiscountPolicy(50);
    expect(p.computeDiscountCents(-1000)).toBe(0);
  });

  it("handles very large subtotals", () => {
    const p = new PercentageDiscountPolicy(15);
    expect(p.computeDiscountCents(999_999_999)).toBe(
      Math.floor((999_999_999 * 15) / 100),
    );
  });
});

describe("FixedAmountDiscountPolicy", () => {
  it("rejects negative amountCents", () => {
    expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
  });

  it("rejects non-integer amountCents", () => {
    expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
  });

  it("accepts 0", () => {
    const p = new FixedAmountDiscountPolicy(0);
    expect(p.computeDiscountCents(5000)).toBe(0);
  });

  it("returns the fixed amount when subtotal exceeds it", () => {
    const p = new FixedAmountDiscountPolicy(500);
    expect(p.computeDiscountCents(10_000)).toBe(500);
  });

  it("caps discount at subtotal when fixed amount exceeds subtotal", () => {
    const p = new FixedAmountDiscountPolicy(5000);
    expect(p.computeDiscountCents(3000)).toBe(3000);
  });

  it("returns 0 for zero subtotal", () => {
    const p = new FixedAmountDiscountPolicy(500);
    expect(p.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    const p = new FixedAmountDiscountPolicy(500);
    expect(p.computeDiscountCents(-100)).toBe(0);
  });
});

describe("CompositeDiscountPolicy", () => {
  it("rejects empty policies list", () => {
    expect(() => new CompositeDiscountPolicy([])).toThrow(
      /at least one policy/,
    );
  });

  describe("sum mode", () => {
    it("sums discounts from all child policies against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 1000
          new FixedAmountDiscountPolicy(500), // 500
        ],
        "sum",
      );
      expect(composite.computeDiscountCents(10_000)).toBe(1_500);
    });

    it("order does not matter in sum mode", () => {
      const a = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(500),
          new PercentageDiscountPolicy(10),
        ],
        "sum",
      );
      const b = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10),
          new FixedAmountDiscountPolicy(500),
        ],
        "sum",
      );
      expect(a.computeDiscountCents(10_000)).toBe(
        b.computeDiscountCents(10_000),
      );
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("clamps negative child discount to 0 before summing", () => {
      const negativePolicy = {
        computeDiscountCents: () => -100,
      };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(300)],
        "sum",
      );
      // -100 clamped to 0, + 300 = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially against remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 10000 = 1000; remaining 9000
          new FixedAmountDiscountPolicy(500), // min(500, 9000) = 500
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(10_000)).toBe(1_500);
    });

    it("order matters in chain mode", () => {
      const subtotal = 10_000;
      const a = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(50), // 5000; remaining 5000
          new PercentageDiscountPolicy(50), // 50% of 5000 = 2500
        ],
        "chain",
      );
      const b = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(1000), // 1000; remaining 9000
          new PercentageDiscountPolicy(50), // 50% of 9000 = 4500
        ],
        "chain",
      );
      expect(a.computeDiscountCents(subtotal)).toBe(7_500);
      expect(b.computeDiscountCents(subtotal)).toBe(5_500);
    });

    it("stops giving discounts when remaining is 0", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(10_000), // takes all
          new FixedAmountDiscountPolicy(5_000), // remaining is 0
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(10_000)).toBe(10_000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("clamps negative child discount to 0", () => {
      const negativePolicy = {
        computeDiscountCents: () => -200,
      };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(300)],
        "chain",
      );
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });
  });

  it("defaults to sum mode when mode is omitted", () => {
    const composite = new CompositeDiscountPolicy([
      new PercentageDiscountPolicy(10),
      new FixedAmountDiscountPolicy(500),
    ]);
    expect(composite.computeDiscountCents(10_000)).toBe(1_500);
  });

  it("works with a single policy", () => {
    const composite = new CompositeDiscountPolicy(
      [new PercentageDiscountPolicy(25)],
      "chain",
    );
    expect(composite.computeDiscountCents(10_000)).toBe(2_500);
  });
});

