import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const makeLine = (
  id: string,
  weightGrams: number | undefined,
  quantity: number,
): CartLine => ({
  product: { id, name: id, unitPriceCents: 1000, weightGrams },
  quantity,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for any input", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
    expect(
      calc.computeShippingCents([makeLine("a", 500, 2)], 10_000),
    ).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  it("rejects negative flatCents", () => {
    expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
  });

  it("rejects non-integer flatCents", () => {
    expect(() => new FlatShippingCalculator(5.5)).toThrow(RangeError);
  });

  it("rejects negative freeOverCents", () => {
    expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
  });

  it("rejects non-integer freeOverCents", () => {
    expect(() => new FlatShippingCalculator(500, 10.5)).toThrow(RangeError);
  });

  it("returns 0 for empty cart", () => {
    const calc = new FlatShippingCalculator(500);
    expect(calc.computeShippingCents([], 10_000)).toBe(0);
  });

  it("returns flat fee for non-empty cart", () => {
    const calc = new FlatShippingCalculator(799);
    expect(
      calc.computeShippingCents([makeLine("a", 100, 1)], 5000),
    ).toBe(799);
  });

  it("returns 0 when subtotal meets freeOverCents threshold", () => {
    const calc = new FlatShippingCalculator(799, 5000);
    expect(
      calc.computeShippingCents([makeLine("a", 100, 1)], 5000),
    ).toBe(0);
  });

  it("returns 0 when subtotal exceeds freeOverCents threshold", () => {
    const calc = new FlatShippingCalculator(799, 5000);
    expect(
      calc.computeShippingCents([makeLine("a", 100, 1)], 6000),
    ).toBe(0);
  });

  it("charges flat fee when subtotal is below freeOverCents", () => {
    const calc = new FlatShippingCalculator(799, 5000);
    expect(
      calc.computeShippingCents([makeLine("a", 100, 1)], 4999),
    ).toBe(799);
  });

  it("accepts 0 flatCents", () => {
    const calc = new FlatShippingCalculator(0);
    expect(
      calc.computeShippingCents([makeLine("a", 100, 1)], 5000),
    ).toBe(0);
  });

  it("accepts 0 freeOverCents (always free for non-empty cart with subtotal >= 0)", () => {
    const calc = new FlatShippingCalculator(500, 0);
    expect(
      calc.computeShippingCents([makeLine("a", 100, 1)], 0),
    ).toBe(0);
  });
});

describe("WeightBasedShippingCalculator", () => {
  it("rejects empty brackets", () => {
    expect(() => new WeightBasedShippingCalculator([])).toThrow(
      /at least one/,
    );
  });

  it("rejects bracket with non-positive upToGrams", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
    ).toThrow(RangeError);
  });

  it("rejects bracket with negative costCents", () => {
    expect(
      () =>
        new WeightBasedShippingCalculator([
          { upToGrams: 100, costCents: -1 },
        ]),
    ).toThrow(RangeError);
  });

  it("rejects non-integer upToGrams", () => {
    expect(
      () =>
        new WeightBasedShippingCalculator([
          { upToGrams: 100.5, costCents: 100 },
        ]),
    ).toThrow(RangeError);
  });

  it("rejects non-integer costCents", () => {
    expect(
      () =>
        new WeightBasedShippingCalculator([
          { upToGrams: 100, costCents: 10.5 },
        ]),
    ).toThrow(RangeError);
  });

  it("rejects negative overflowCostCents", () => {
    expect(
      () =>
        new WeightBasedShippingCalculator(
          [{ upToGrams: 100, costCents: 100 }],
          -1,
        ),
    ).toThrow(RangeError);
  });

  it("rejects non-integer overflowCostCents", () => {
    expect(
      () =>
        new WeightBasedShippingCalculator(
          [{ upToGrams: 100, costCents: 100 }],
          5.5,
        ),
    ).toThrow(RangeError);
  });

  it("returns 0 for empty cart", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
    ]);
    expect(calc.computeShippingCents([], 10_000)).toBe(0);
  });

  it("returns 0 when total weight is 0", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
    ]);
    expect(
      calc.computeShippingCents([makeLine("a", undefined, 2)], 10_000),
    ).toBe(0);
  });

  it("selects the correct bracket", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 500 },
      { upToGrams: 2000, costCents: 800 },
    ]);
    // 400g → bracket 500
    expect(
      calc.computeShippingCents([makeLine("a", 400, 1)], 10_000),
    ).toBe(300);
    // 600g → bracket 1000
    expect(
      calc.computeShippingCents([makeLine("a", 600, 1)], 10_000),
    ).toBe(500);
    // 1500g → bracket 2000
    expect(
      calc.computeShippingCents([makeLine("a", 1500, 1)], 10_000),
    ).toBe(800);
  });

  it("uses bracket boundary (weight exactly equals upToGrams)", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 500 },
    ]);
    expect(
      calc.computeShippingCents([makeLine("a", 500, 1)], 10_000),
    ).toBe(300);
    expect(
      calc.computeShippingCents([makeLine("a", 1000, 1)], 10_000),
    ).toBe(500);
  });

  it("uses overflow cost when weight exceeds all brackets", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 500 },
      ],
      999,
    );
    expect(
      calc.computeShippingCents([makeLine("a", 1500, 1)], 10_000),
    ).toBe(999);
  });

  it("falls back to heaviest bracket cost when no overflow specified", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 500 },
    ]);
    expect(
      calc.computeShippingCents([makeLine("a", 5000, 1)], 10_000),
    ).toBe(500);
  });

  it("sorts brackets internally regardless of input order", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
      { upToGrams: 500, costCents: 300 },
    ]);
    expect(
      calc.computeShippingCents([makeLine("a", 400, 1)], 10_000),
    ).toBe(300);
  });

  it("sums weight across multiple lines with quantity", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 2000, costCents: 700 },
    ]);
    // 200*2 + 300*1 = 700g → bracket 2000
    const lines = [makeLine("a", 200, 2), makeLine("b", 300, 1)];
    expect(calc.computeShippingCents(lines, 10_000)).toBe(700);
  });
});

